<?php session_start();require_once __DIR__.'/../../src/db.php';require_once __DIR__.'/../../src/upload.php';if(!($_SESSION['admin']??false)){header('Location:/admin/');exit;}$db=db();try{$db->exec('ALTER TABLE tour_scenes ADD COLUMN duration_seconds INTEGER DEFAULT NULL');}catch(Throwable $ignored){}$edit=(int)($_GET['edit']??$_POST['tour_id']??0);
if(isset($_GET['delete_scene'])){$q=$db->prepare("DELETE FROM tour_scenes WHERE id=? AND tour_id=?");$q->execute([(int)$_GET['delete_scene'],$edit]);header('Location:?edit='.$edit);exit;}
if(isset($_GET['move'],$edit)&&$edit){$id=(int)$_GET['move'];$dir=$_GET['dir']??'';$q=$db->prepare("SELECT id,sort_order FROM tour_scenes WHERE tour_id=? ORDER BY sort_order,id");$q->execute([$edit]);$rows=$q->fetchAll();foreach($rows as $i=>$r)if((int)$r['id']===$id){$j=$dir==='up'?$i-1:$i+1;if(isset($rows[$j])){$db->beginTransaction();$a=$db->prepare("UPDATE tour_scenes SET sort_order=? WHERE id=?");$a->execute([$rows[$j]['sort_order'],$id]);$a->execute([$r['sort_order'],$rows[$j]['id']]);$db->commit();}break;}header('Location:?edit='.$edit);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['save_tour'])&&$edit){$cover=$tourRow['cover']??'';if(($_FILES['cover_file']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK)$cover='/uploads/'.storeUploadedImage($_FILES['cover_file'],UPLOAD_DIR);$q=$db->prepare("UPDATE tours SET title=?,slug=?,description=?,published=?,start_scene_id=?,cover=? WHERE id=?");$slug=preg_replace('/[^a-z0-9]+/','-',strtolower(trim($_POST['slug'])));$q->execute([trim($_POST['title']),$slug,trim($_POST['description']),isset($_POST['published'])?1:0,($_POST['start_scene_id']??'')!==''?(int)$_POST['start_scene_id']:null,$cover,$edit]);header('Location:?edit='.$edit);exit;}if(isset($_POST['save_scene'])&&$edit){$q=$db->prepare("UPDATE tour_scenes SET title=?,duration_seconds=? WHERE id=? AND tour_id=?");$q->execute([trim($_POST['scene_title']),($_POST['duration_seconds']??'')===''?null:max(0,min(3600,(int)$_POST['duration_seconds'])),(int)$_POST['scene_id'],$edit]);header('Location:?edit='.$edit);exit;}if(isset($_POST['create'])){$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($_POST['slug']?:bin2hex(random_bytes(4))));$q=$db->prepare("INSERT INTO tours(title,slug,description,published) VALUES(?,?,?,1)");$q->execute([trim($_POST['title']),$slug,trim($_POST['description'])]);header('Location:?edit='.$db->lastInsertId());exit;}if(isset($_POST['add_scene'])){$max=(int)$db->query("SELECT COALESCE(MAX(sort_order),0) FROM tour_scenes WHERE tour_id=".$edit)->fetchColumn();$q=$db->prepare("INSERT INTO tour_scenes(tour_id,panorama_id,title,sort_order) VALUES(?,?,?,?)");$q->execute([$edit,(int)$_POST['panorama_id'],trim($_POST['scene_title']),$max+10]);header('Location:?edit='.$edit);exit;}}
$tours=$db->query("SELECT * FROM tours ORDER BY id DESC")->fetchAll();$panos=$db->query("SELECT * FROM panoramas ORDER BY title")->fetchAll();$scenes=[];$tourRow=null;if($edit){$q=$db->prepare("SELECT * FROM tours WHERE id=?");$q->execute([$edit]);$tourRow=$q->fetch();$q=$db->prepare("SELECT s.*,p.image,p.preview,p.title panorama_title,p.projection,p.stereo,(SELECT COUNT(*) FROM hotspots h WHERE h.scene_id=s.id) hotspot_count FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.tour_id=? ORDER BY s.sort_order,s.id");$q->execute([$edit]);$scenes=$q->fetchAll();}?>
